      "properties": {
        "file_types": {
          "description": "Only search files with these extensions, e.g., [\".rs\", \".toml\"]",
          "items": {
            "type": "string"
          },
          "type": "array"
        },
        "max_results": {
          "description": "Maximum number of results to return (default: 50, max: 200)",
          "type": "integer"
        },
        "path": {
          "description": "File or directory to search (relative path)",
          "type": "string"
        },
        "pattern": {
          "description": "Text pattern to search for",
          "type": "string"
        },
        "regex": {
          "description": "Use regex search via regex-lite (default: false)",
          "type": "boolean"
        }
      },
      "required": [
        "path",
        "pattern"
      ],
      "type": "object"
    }
  },
  {
    "name": "read_skill",
    "description": "Load the full instructions of a review skill by name. The system prompt only lists skill names and descriptions; call this before reporting findings to apply a skill's rules.",
